+const { useState, useRef } = React;
+
+const OPTIONS = [
+  { value: "email", label: "Email" },
+  { value: "sms", label: "SMS" },
+  { value: "push", label: "Push Notifications" },
+];
+
+function NotificationPreferenceField({ value, onChange, error, errorId, fieldsetRef }) {
+  return (
+    <div className="form-field">
+      <fieldset
+        ref={fieldsetRef}
+        aria-describedby={error ? errorId : undefined}
+      >
+        <legend>
+          How do you prefer to receive notifications?
+          <span className="required-marker" aria-hidden="true">*</span>
+        </legend>
+        <div className="radio-group" role="presentation">
+          {OPTIONS.map((opt) => {
+            const id = `notify-${opt.value}`;
+            return (
+              <label key={opt.value} className="radio-option" htmlFor={id}>
+                <input
+                  id={id}
+                  type="radio"
+                  name="notification-preference"
+                  value={opt.value}
+                  checked={value === opt.value}
+                  onChange={(e) => onChange(e.target.value)}
+                  required
+                  aria-invalid={error ? "true" : undefined}
+                />
+                <span className="label-text">{opt.label}</span>
+              </label>
+            );
+          })}
+        </div>
+        {error && (
+          <p id={errorId} className="error-text">Error: {error}</p>
+        )}
+      </fieldset>
+    </div>
+  );
+}
+
+function PreferencesForm() {
+  const [value, setValue] = useState("");
+  const [error, setError] = useState("");
+  const [submitted, setSubmitted] = useState(null);
+  const fieldsetRef = useRef(null);
+  const errorId = "notify-error";
+
+  const handleChange = (next) => {
+    setValue(next);
+    if (error) setError("");
+  };
+
+  const handleSubmit = (e) => {
+    e.preventDefault();
+    if (!value) {
+      setError("Choose how you want to receive notifications.");
+      setSubmitted(null);
+      const firstRadio = fieldsetRef.current?.querySelector('input[type="radio"]');
+      firstRadio?.focus();
+      return;
+    }
+    const labelFor = OPTIONS.find((o) => o.value === value)?.label;
+    setSubmitted(labelFor);
+  };
+
+  return (
+    <form noValidate onSubmit={handleSubmit}>
+      <p className="required-note">
+        <span className="required-marker" aria-hidden="true">*</span> indicates a required field.
+      </p>
+
+      <NotificationPreferenceField
+        value={value}
+        onChange={handleChange}
+        error={error}
+        errorId={errorId}
+        fieldsetRef={fieldsetRef}
+      />
+
+      <div className="actions">
+        <button type="submit" className="btn-primary">Save preferences</button>
+      </div>
+
+      <div aria-live="polite" role="status">
+        {submitted && (
+          <p className="status">Preferences saved. We'll notify you via {submitted}.</p>
+        )}
+      </div>
+    </form>
+  );
+}
+
+function App() {
+  return (
+    <div className="page">
+      <header className="page-header">
+        <div className="brand">Acme Notifications</div>
+      </header>
+      <main id="main" className="main">
+        <section className="card" aria-labelledby="page-title">
+          <h1 id="page-title">Notification preferences</h1>
+          <p className="lede">Tell us where to send important updates about your account.</p>
+          <PreferencesForm />
+        </section>
+      </main>
+    </div>
+  );
+}
+
+ReactDOM.createRoot(document.getElementById("root")).render(<App />);
